import re

def error_report(log_text: str) -> list:
    lines = log_text.split()
    error_counts = {}

    for line in lines:
        if not line:
            continue
        # Regular expression to match valid log line format
        if re.match(r'^(\d{2}:-?\d{2}-(\d{2}|\d{1}:-\d{1}|\d{1}:-\d{1}|\d{1}:-\d{1}))$', line):
            timestamp, message = line.split('-')
            hour = int(timestamp[:2])
            if 'INFO' in (msg for msg in message.split() if msg.lower() in ('info', 'error', 'warning')):
                error_counts[hour] = error_counts.get(hour, 0) + 1

    result = []
    for hour in sorted(error_counts.keys()):
        count = error_counts[hour]
        if count > 0:
            result.append(f"{hour:02d}: {count} errors")

    return result


