import re
from collections import defaultdict

def summarize_expenses(csv_text: str) -> dict:
    lines = csv_text.strip().split('\n')

    if not lines or len(lines) < 2:
        return {}

    totals = defaultdict(float)

    for line in lines[1:]:  # Skip header row
        line = line.strip()
        if not line:
            continue

        parts = line.split(',')
        if len(parts) < 3:
            continue

        category = parts[1].strip().lower()
        amount_str = parts[2].strip()

        # Skip if amount is empty
        if not amount_str:
            continue

        try:
            # Remove $ sign and commas
            amount_str_clean = amount_str.replace('$', '').replace(',', '')

            # Check for parentheses (negative accounting style)
            if amount_str.startswith('(') and amount_str.endswith(')'):
                amount = -float(amount_str_clean[1:-1])
            else:
                amount = float(amount_str_clean)
        except ValueError:
            continue

        totals[category] += amount

    # Round to 2 decimals and convert to regular dict
    return {cat: round(total, 2) for cat, total in totals.items()}


